+            {
+                return MemoryOperationResult<FlatArtifactIndex>.Reject(MemoryFailure.BoundsViolation);
+            }
+            if (mutation.Replacement is null)
+            {
+                next.Remove(mutation.Id);
+            }
+            else
+            {
