+        {
+            const context = cppCompileContext(root, entry);
+            if (cache.match(/^CMAKE_CXX_COMPILER:(?:FILEPATH|STRING)=(.+)$/mu)?.[1] !== context.compiler)
+            {
+                throw new Error('C++ compiler differs from the actual CMake context');
